1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::fs;
4	use std::path::Path;
5	use std::process::ExitCode;
6	
7	use roottrace::{hex, hex_nibble, is_lower_hex, mth, proof_json, root_and_path, split_records};
8	
9	const VERSION: &str = "0.1.0";
10	
11	const USAGE: &str = "\
12	Usage:
13	    roottrace root <file>
14	    roottrace prove <file> <record-index>
15	    roottrace verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
16	    roottrace --version
17	
18	Commands:
19	    root <file>
20	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
21	        as one line of 64 lowercase hexadecimal characters.
22	
23	    prove <file> <record-index>
24	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
25	        record at <record-index> within the whole batch. The index is
26	        0-based and counts records in file order: 0 is the first record,
27	        1 the second, and so on; the same content at multiple positions gets
28	        the proof for the exact position given, with no deduplication. Output
29	        is one JSON object with the fields tree_size, leaf_index, root and
30	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
31	        exactly one record).
32	
33	        Example:
34	            roottrace prove batch.txt 0
35	
36	    verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
37	        Verify an inclusion proof produced by `prove` without needing the
38	        whole batch. The record file holds the raw bytes of exactly one
39	        target record (no LF splitting, byte for byte including any trailing
40	        LF/space/CR, NUL and non-UTF-8 bytes; an empty file is one empty
41	        record). The proof is read as one complete JSON object. The trusted
42	        tree size (an ASCII decimal positive integer) and the trusted root
43	        (64 lowercase hexadecimal characters) must be confirmed
44	        independently; they are never taken from fields inside the proof.
45	        On success stdout is exactly \"verified\\n\", stderr is empty and the
46	        exit status is 0.
47	
48	        Example:
49	            roottrace verify record.bin proof.json 9 a8a3e76e...723adc3
50	
51	Exit status:
52	    0  success
53	    1  an input file cannot be read, the proof is malformed, or verification fails
54	    2  usage error (unknown command, missing or extra arguments, bad arguments)";
55	
56	fn main() -> ExitCode {
57	    // Raw OS arguments: file paths are handed to the filesystem exactly as
58	    // received, byte for byte. On Unix a path may contain bytes that are not
59	    // valid UTF-8 (e.g. 0xff); such a path is not invalid and must reach the
60	    // file rather than aborting argument collection. The command name, the
61	    // record index and the trusted tree size/root arguments are required to
62	    // be UTF-8 text.
63	    let args: Vec<OsString> = env::args_os().skip(1).collect();
64	    match args.as_slice() {
65	        [flag] if flag == OsStr::new("--version") => {
66	            println!("roottrace {VERSION}");
67	            ExitCode::SUCCESS
68	        }
69	        [cmd, path] if cmd == OsStr::new("root") => match merkle_root_of_file(Path::new(path)) {
70	            Ok(root) => {
71	                println!("{}", hex(&root));
72	                ExitCode::SUCCESS
73	            }
74	            Err(reason) => {
75	                eprintln!("roottrace: {reason}");
76	                ExitCode::FAILURE
77	            }
78	        },
79	        [cmd, path, index] if cmd == OsStr::new("prove") => match parse_index(index) {
80	            Some(index) => match proof_for_file(Path::new(path), index) {
81	                Ok(proof) => {
82	                    println!("{}", proof);
83	                    ExitCode::SUCCESS
84	                }
85	                Err(ProveError::Read(reason)) => {
86	                    eprintln!("roottrace: {reason}");
87	                    ExitCode::FAILURE
88	                }
89	                Err(ProveError::Missing(index, size)) => {
90	                    if size == 0 {
91	                        eprintln!(
92	                            "roottrace: record index {index} does not exist: the file holds zero records"
93	                        );
94	                    } else {
95	                        eprintln!(
96	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
97	                            size - 1
98	                        );
99	                    }
100	                    ExitCode::FAILURE
101	                }
102	            },
103	            None => {
104	                let shown = index.to_string_lossy();
105	                eprintln!("roottrace: invalid record index '{shown}': expected a decimal non-negative integer of ASCII digits");
106	                eprintln!("{USAGE}");
107	                ExitCode::from(2)
108	            }
109	        },
110	        [cmd, path, proof_path, size_arg, root_arg] if cmd == OsStr::new("verify") => {
111	            match (parse_trusted_size(size_arg), parse_trusted_root(root_arg)) {
112	                (Some(trusted_size), Some(trusted_root)) => {
113	                    match verify_files(Path::new(path), Path::new(proof_path), trusted_size, &trusted_root) {
114	                        Ok(()) => {
115	                            println!("verified");
116	                            ExitCode::SUCCESS
117	                        }
118	                        Err(VerifyError::Read { path, source }) => {
119	                            eprintln!(
120	                                "roottrace: cannot read '{}': {source}",
121	                                display_path(&path)
122	                            );
123	                            ExitCode::FAILURE
124	                        }
125	                        Err(VerifyError::MalformedProof(reason)) => {
126	                            eprintln!("roottrace: invalid proof: {reason}");
127	                            ExitCode::FAILURE
128	                        }
129	                        Err(VerifyError::Failed(reason)) => {
130	                            eprintln!("roottrace: verification failed: {reason}");
131	                            ExitCode::FAILURE
132	                        }
133	                    }
134	                }
135	                (bad_size, bad_root) => {
136	                    if bad_size.is_none() {
137	                        let shown = size_arg.to_string_lossy();
138	                        eprintln!(
139	                            "roottrace: invalid trusted tree size '{shown}': expected an ASCII decimal positive integer within unsigned 64-bit range"
140	                        );
141	                    }
142	                    if bad_root.is_none() {
143	                        let shown = root_arg.to_string_lossy();
144	                        eprintln!(
145	                            "roottrace: invalid trusted root '{shown}': expected exactly 64 lowercase hexadecimal characters"
146	                        );
147	                    }
148	                    eprintln!("{USAGE}");
149	                    ExitCode::from(2)
150	                }
151	            }
152	        }
153	        _ => {
154	            eprintln!("{USAGE}");
155	            ExitCode::from(2)
156	        }
157	    }
158	}
159	
160	enum ProveError {
161	    Read(String),
162	    Missing(u64, u64),
163	}
164	
165	/// Failures reported by `verify`, kept separate so that malformed proofs and
166	/// cryptographic mismatches both exit 1 but say different things on stderr.
167	enum VerifyError {
168	    /// One of the two input paths cannot be read (missing, a directory, ...).
169	    Read { path: std::path::PathBuf, source: std::io::Error },
170	    /// The proof bytes are not a well-formed proof object.
171	    MalformedProof(String),
172	    /// The proof is well-formed but does not establish the claimed inclusion
173	    /// against the independently trusted tree size and root.
174	    Failed(String),
175	}
176	
177	/// Read the two input files and run an RFC 6962 inclusion check. The record
178	/// file's ENTIRE byte content is the target record: no LF splitting and no
179	/// trimming of trailing LF, space or CR; NUL and non-UTF-8 bytes take part as
180	/// they are. A zero-byte file is one empty record. The check itself is the
181	/// library entry point `roottrace::verify_membership`, so the command and
182	/// Rust callers of the library share exactly one verification path.
183	fn verify_files(
184	    record_path: &Path,
185	    proof_path: &Path,
186	    trusted_size: u64,
187	    trusted_root: &[u8; 32],
188	) -> Result<(), VerifyError> {
189	    let record = fs::read(record_path).map_err(|source| VerifyError::Read {
190	        path: record_path.to_path_buf(),
191	        source,
192	    })?;
193	    let proof_bytes = fs::read(proof_path).map_err(|source| VerifyError::Read {
194	        path: proof_path.to_path_buf(),
195	        source,
196	    })?;
197	    match roottrace::verify_membership(&record, &proof_bytes, trusted_size, trusted_root) {
198	        Ok(_) => Ok(()),
199	        Err(roottrace::VerifyError::MalformedProof(reason)) => {
200	            Err(VerifyError::MalformedProof(reason))
201	        }
202	        Err(roottrace::VerifyError::VerificationFailed(reason)) => Err(VerifyError::Failed(reason)),
203	        // parse_trusted_size rejects zero before this function is ever
204	        // called, so the library's invalid-argument case cannot occur here.
205	        Err(roottrace::VerifyError::InvalidTrustedSize) => {
206	            unreachable!("the command line only accepts a positive trusted tree size")
207	        }
208	    }
209	}
210	
211	/// Parse the trusted tree size given on the command line: one or more ASCII
212	/// decimal digits naming a POSITIVE 64-bit unsigned integer. Unlike a record
213	/// index, zero is not accepted (it cannot be a tree that contains a record).
214	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
215	/// is a usage error.
216	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
217	    let text = arg.to_str()?;
218	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
219	        return None;
220	    }
221	    let mut value: u64 = 0;
222	    for b in text.bytes() {
223	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
224	    }
225	    if value == 0 {
226	        return None;
227	    }
228	    Some(value)
229	}
230	
231	/// Parse the trusted root given on the command line: exactly 64 lowercase
232	/// ASCII hexadecimal characters (32 bytes). Uppercase, wrong length, non-hex
233	/// or non-UTF-8 bytes are usage errors.
234	fn parse_trusted_root(arg: &OsStr) -> Option<[u8; 32]> {
235	    let text = arg.to_str()?;
236	    if text.len() != 64 || !text.bytes().all(is_lower_hex) {
237	        return None;
238	    }
239	    let bytes = text.as_bytes();
240	    let mut out = [0u8; 32];
241	    for (i, pair) in bytes.chunks_exact(2).enumerate() {
242	        out[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
243	    }
244	    Some(out)
245	}
246	
247	/// Render a path for a human-readable error message. This is used ONLY in
248	/// diagnostics: the filesystem is always given the raw `Path`, never this
249	/// lossy rendering, so a file whose name contains 0xff is not confused with a
250	/// differently named file that merely displays the same way.
251	fn display_path(path: &Path) -> String {
252	    path.to_string_lossy().into_owned()
253	}
254	
255	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
256	    let data = fs::read(path).map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
257	    Ok(mth(&split_records(&data)))
258	}
259	
260	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
261	    let data = fs::read(path)
262	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
263	    let records = split_records(&data);
264	    let size = records.len() as u64;
265	    if index >= size {
266	        return Err(ProveError::Missing(index, size));
267	    }
268	    let idx = index as usize;
269	    let (root, audit_path) = root_and_path(&records, idx);
270	    Ok(proof_json(size, index, &root, &audit_path))
271	}
272	
273	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
274	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
275	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
276	/// UTF-8) is rejected as a usage error.
277	fn parse_index(arg: &OsStr) -> Option<u64> {
278	    let text = arg.to_str()?;
279	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
280	        return None;
281	    }
282	    let mut value: u64 = 0;
283	    for b in text.bytes() {
284	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
285	    }
286	    Some(value)
287	}
288	
289	#[cfg(test)]
290	mod tests {
291	    use super::*;
292	    use std::os::unix::ffi::OsStrExt;
293	
294	    #[test]
295	    fn index_parsing_accepts_only_ascii_unsigned_decimal() {
296	        assert_eq!(parse_index(OsStr::new("0")), Some(0));
297	        assert_eq!(parse_index(OsStr::new("00")), Some(0));
298	        assert_eq!(parse_index(OsStr::new("123")), Some(123));
299	        assert_eq!(parse_index(OsStr::new("18446744073709551615")), Some(u64::MAX));
300	        assert_eq!(parse_index(OsStr::new("18446744073709551616")), None);
301	        assert_eq!(parse_index(OsStr::new("")), None);
302	        assert_eq!(parse_index(OsStr::new("-1")), None);
303	        assert_eq!(parse_index(OsStr::new("+1")), None);
304	        assert_eq!(parse_index(OsStr::new("1.0")), None);
305	        assert_eq!(parse_index(OsStr::new(" 1")), None);
306	        assert_eq!(parse_index(OsStr::new("1 ")), None);
307	        assert_eq!(parse_index(OsStr::new("0x1")), None);
308	        assert_eq!(parse_index(OsStr::new("①")), None);
309	        // Leading-zero overflow is still overflow.
310	        assert_eq!(parse_index(OsStr::new("0018446744073709551616")), None);
311	        // An argument that is not valid UTF-8 is a usage error, never a panic.
312	        assert_eq!(parse_index(OsStr::from_bytes(b"1\xff")), None);
313	        assert_eq!(parse_index(OsStr::from_bytes(b"\xff")), None);
314	    }
315	
316	    // --- trusted command-line arguments -------------------------------------
317	
318	    #[test]
319	    fn trusted_size_accepts_only_positive_ascii_decimal_u64() {
320	        assert_eq!(parse_trusted_size(OsStr::new("1")), Some(1));
321	        assert_eq!(parse_trusted_size(OsStr::new("09")), Some(9));
322	        assert_eq!(parse_trusted_size(OsStr::new("18446744073709551615")), Some(u64::MAX));
323	        // Zero is not a tree that can contain a record.
324	        assert_eq!(parse_trusted_size(OsStr::new("0")), None);
325	        assert_eq!(parse_trusted_size(OsStr::new("00")), None);
326	        for bad in ["", "-1", "+1", "1.0", " 1", "1 ", "0x1", "18446744073709551616", "①"] {
327	            assert_eq!(parse_trusted_size(OsStr::new(bad)), None, "size {bad:?}");
328	        }
329	        assert_eq!(parse_trusted_size(OsStr::from_bytes(b"9\xff")), None);
330	    }
331	
332	    #[test]
333	    fn trusted_root_accepts_exactly_64_lowercase_hex() {
334	        let h = hex(&mth(&[b"a"]));
335	        let parsed = parse_trusted_root(OsStr::new(&h)).expect("valid root");
336	        assert_eq!(parsed, mth(&[b"a"]));
337	        for bad in [
338	            "",
339	            &"a".repeat(63),
340	            &"a".repeat(65),
341	            // One uppercase digit.
342	            &{
343	                let mut s = h.clone();
344	                s.replace_range(0..1, "A");
345	                s
346	            },
347	            &format!("{h} "),
348	            &format!(" {h}"),
349	            &"z".repeat(64),
350	        ] {
351	            assert!(parse_trusted_root(OsStr::new(bad)).is_none(), "root {bad:?}");
352	        }
353	        assert!(parse_trusted_root(OsStr::from_bytes(&[b'a'; 65])).is_none());
354	    }
355	}
