58	use std::fmt;
59	
60	/// 核验成功后的类型化结果：记录在某个 Merkle 树中的成员身份已被确认。
61	///
62	/// 序号从 0 开始，指向证明声明的位置；相同内容出现在其他位置不能替代这个
63	/// 位置。树大小和根值已经与调用方的可信值核对一致——它们就是核验所锚定的
64	/// 值，而不是从证明中读出的字段。
65	#[derive(Debug, Clone, PartialEq, Eq)]
66	pub struct Membership {
67	    leaf_index: u64,
68	    tree_size: u64,
69	    root: [u8; 32],
70	}
71	
72	impl Membership {
73	    /// 被核验记录在树中的序号（从 0 开始），即证明声明的 `leaf_index`。
74	    /// 即使树大小超过平台的索引宽度，也保留完整的 64 位含义。
75	    pub fn leaf_index(&self) -> u64 {
76	        self.leaf_index
77	    }
78	
79	    /// 核验所绑定的树大小，等于调用方提供的可信树大小。
80	    pub fn tree_size(&self) -> u64 {
81	        self.tree_size
82	    }
83	
84	    /// 核验所绑定的树根值，等于调用方提供的可信根值。
85	    pub fn root(&self) -> &[u8; 32] {
86	        &self.root
87	    }
88	}
89	
90	/// 核验失败的分类，调用方可按变体区分处理方式。
91	#[derive(Debug, Clone, PartialEq, Eq)]
92	pub enum VerifyError {
93	    /// 调用参数无效：可信树大小为 0。不存在包含记录的零节点树，因此这不
94	    /// 能被当作"空树中的成员证明"接受。该判断在解读证明之前完成。
95	    InvalidTrustedSize,
96	    /// 证明格式无效：证明字节不能按现有格式解读（不是完整 JSON 对象、字段
97	    /// 缺失/重复/类型错误、整数或哈希不合法、`tree_size` 为 0、序号越界、
98	    /// 对象后有多余字节等）。附带人类可读的原因说明。
99	    MalformedProof(String),
100	    /// 核验失败：证明格式合法，但记录内容、可信树大小、可信根值或审计路径
101	    /// 不匹配。附带人类可读的原因说明。
102	    VerificationFailed(String),
103	}
104	
105	impl fmt::Display for VerifyError {
106	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
107	        match self {
108	            VerifyError::InvalidTrustedSize => {
109	                write!(f, "trusted tree size must be positive: zero cannot name a tree that holds a record")
110	            }
111	            VerifyError::MalformedProof(reason) => write!(f, "invalid proof: {reason}"),
112	            VerifyError::VerificationFailed(reason) => write!(f, "verification failed: {reason}"),
113	        }
114	    }
115	}
116	
117	impl std::error::Error for VerifyError {}
118	
119	/// 核验一条记录的 RFC 6962 成员证明，无需完整批次或临时文件。
120	///
121	/// - `record`：目标记录的全部原始字节。空切片表示一条空记录；末尾 LF、CR、
122	///   空格、NUL 与非 UTF-8 字节都属于内容，不做任何切分或修剪。
123	/// - `proof`：证明 JSON 的原始字节（如 `roottrace prove` 的输出）。字段
124	///   重排、合法空白与等价字符串转义被接受；重复字段、不合法的整数或哈希
125	///   被拒绝。
126	/// - `trusted_tree_size`：调用方**独立确认**的树大小，必须为正；为 0 时
127	///   返回 [`VerifyError::InvalidTrustedSize`]，而不是按空树核验。
128	/// - `trusted_root`：调用方**独立确认**的 32 字节根值。
129	///
130	/// 证明自带的 `tree_size` 与 `root` 只用于和可信值比对，绝不作为信任依据。
131	/// 成功时返回 [`Membership`]；失败时按 [`VerifyError`] 变体区分格式错误与
132	/// 核验失败，且不会返回任何表示已核验成功的结果。
133	pub fn verify_membership(
134	    record: &[u8],
135	    proof: &[u8],
136	    trusted_tree_size: u64,
137	    trusted_root: &[u8; 32],
138	) -> Result<Membership, VerifyError> {
139	    // 可信树大小为零是调用参数无效：必须先于证明解读拒绝，否则一份
140	    // tree_size 为 0 的"证明"会被当成空树成员证明的格式问题来报告。
141	    if trusted_tree_size == 0 {
142	        return Err(VerifyError::InvalidTrustedSize);
143	    }
144	    let proof = parse_proof(proof).map_err(VerifyError::MalformedProof)?;
145	    verify_proof(&proof, record, trusted_tree_size, trusted_root)
146	        .map_err(VerifyError::VerificationFailed)?;
147	    Ok(Membership {
148	        leaf_index: proof.leaf_index,
149	        tree_size: trusted_tree_size,
150	        root: *trusted_root,
151	    })
152	}
153	
154	// --- 供命令行程序复用的内部实现 ------------------------------------------------
155	//
156	// 以下项是 `roottrace` 命令行程序（src/main.rs）与库共享的实现细节，不属于
157	// 稳定的库 API，故对文档隐藏。命令行的 root/prove/verify 子命令与库函数走
158	// 完全相同的代码路径，保证两边结果一致。
159	
160	#[doc(hidden)]
161	pub fn is_lower_hex(b: u8) -> bool {
162	    b.is_ascii_digit() || (b'a'..=b'f').contains(&b)
163	}
164	
165	#[doc(hidden)]
166	pub fn hex_nibble(b: u8) -> Option<u8> {
167	    match b {
168	        b'0'..=b'9' => Some(b - b'0'),
169	        b'a'..=b'f' => Some(b - b'a' + 10),
170	        _ => None,
171	    }
172	}
173	
174	// --- Proof parsing -----------------------------------------------------------
175	//
176	// The proof must be ONE complete JSON object. `prove` output is plain JSON,
177	// but the file may also arrive over a channel that reorders fields or changes
178	// whitespace, so both are accepted. Nothing else is: a truncated value, a
179	// duplicate key, a value of the wrong JSON type, a number that is not an
180	// exact unsigned 64-bit integer, a non-lowercase/non-64-char hash, trailing
181	// bytes after the object, or an empty file all make the proof invalid.
182	// Parsing is structural: no text decoding of the proof is required for the
183	// hashes, and integer fields are accumulated digit by digit so a value above
184	// u64::MAX (including 1e400) is rejected rather than wrapped or approximated.
185	
186	/// The fields of a well-formed inclusion proof.
187	struct Proof {
188	    tree_size: u64,
189	    leaf_index: u64,
190	    root: [u8; 32],
191	    audit_path: Vec<[u8; 32]>,
192	}
193	
194	struct ProofParser<'a> {
195	    bytes: &'a [u8],
196	    pos: usize,
197	}
198	
199	fn parse_proof(input: &[u8]) -> Result<Proof, String> {
200	    let mut p = ProofParser { bytes: input, pos: 0 };
201	    p.ws();
202	    let proof = p.parse_object().map_err(|e| e.to_string())?;
203	    p.ws();
204	    if p.pos != p.bytes.len() {
205	        return Err("trailing data after the JSON object".to_string());
206	    }
207	    let tree_size = proof.tree_size.ok_or_else(|| "missing field 'tree_size'".to_string())?;
208	    let leaf_index = proof.leaf_index.ok_or_else(|| "missing field 'leaf_index'".to_string())?;
209	    let root = proof.root.ok_or_else(|| "missing field 'root'".to_string())?;
210	    let audit_path =
211	        proof.audit_path.ok_or_else(|| "missing field 'audit_path'".to_string())?;
212	    if tree_size == 0 {
213	        return Err("tree_size must be positive".to_string());
214	    }
215	    if leaf_index >= tree_size {
216	        return Err(format!(
217	            "leaf_index {leaf_index} is out of range for tree_size {tree_size}"
218	        ));
219	    }
220	    Ok(Proof { tree_size, leaf_index, root, audit_path })
221	}
222	
223	/// Accumulator for the four recognised object members; a `Some` already
224	/// present when the same key is seen again makes the proof invalid.
225	struct ProofFields {
226	    tree_size: Option<u64>,
227	    leaf_index: Option<u64>,
228	    root: Option<[u8; 32]>,
229	    audit_path: Option<Vec<[u8; 32]>>,
230	}
231	
232	impl<'a> ProofParser<'a> {
233	    fn ws(&mut self) {
234	        while self.pos < self.bytes.len() && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
235	            self.pos += 1;
236	        }
237	    }
238	
239	    fn peek(&self) -> Option<u8> {
240	        self.bytes.get(self.pos).copied()
241	    }
242	
243	    fn eat(&mut self, b: u8) -> Result<(), String> {
244	        if self.peek() == Some(b) {
245	            self.pos += 1;
246	            Ok(())
247	        } else {
248	            Err(format!("expected '{}' at byte {}", b as char, self.pos))
249	        }
250	    }
251	
252	    fn parse_object(&mut self) -> Result<ProofFields, String> {
253	        self.eat(b'{')?;
254	        let mut fields = ProofFields {
255	            tree_size: None,
256	            leaf_index: None,
257	            root: None,
258	            audit_path: None,
259	        };
260	        self.ws();
261	        if self.peek() == Some(b'}') {
262	            self.pos += 1;
263	            return Err("empty object: none of the required fields are present".to_string());
264	        }
265	        loop {
266	            self.ws();
267	            let key = self.parse_string()?;
268	            self.ws();
269	            self.eat(b':')?;
270	            self.ws();
271	            match key.as_str() {
272	                "tree_size" => {
273	                    if fields.tree_size.is_some() {
274	                        return Err("duplicate field 'tree_size'".to_string());
275	                    }
276	                    fields.tree_size = Some(self.parse_u64()?);
277	                }
278	                "leaf_index" => {
279	                    if fields.leaf_index.is_some() {
280	                        return Err("duplicate field 'leaf_index'".to_string());
281	                    }
282	                    fields.leaf_index = Some(self.parse_u64()?);
283	                }
284	                "root" => {
285	                    if fields.root.is_some() {
286	                        return Err("duplicate field 'root'".to_string());
287	                    }
288	                    fields.root = Some(self.parse_hash()?);
289	                }
290	                "audit_path" => {
291	                    if fields.audit_path.is_some() {
292	                        return Err("duplicate field 'audit_path'".to_string());
293	                    }
294	                    fields.audit_path = Some(self.parse_hash_array()?);
295	                }
296	                other => return Err(format!("unexpected field '{other}'")),
297	            }
298	            self.ws();
299	            match self.peek() {
300	                Some(b',') => {
301	                    self.pos += 1;
302	                }
303	                Some(b'}') => {
304	                    self.pos += 1;
305	                    break;
306	                }
307	                _ => return Err(format!("expected ',' or '}}' at byte {}", self.pos)),
308	            }
309	        }
310	        Ok(fields)
311	    }
312	
313	    /// A JSON string returned as UTF-8 text. Proof keys are ASCII; escapes
314	    /// (including `\uXXXX`) are decoded so a spelled-out key cannot bypass the
315	    /// recognized-name matching. Any string value anywhere is gated through
316	    /// here, so invalid escapes or an unclosed string reject the proof.
317	    fn parse_string(&mut self) -> Result<String, String> {
318	        self.eat(b'"')?;
319	        let mut out = String::new();
320	        loop {
321	            match self.peek() {
322	                None => return Err("unterminated string".to_string()),
323	                Some(b'"') => {
324	                    self.pos += 1;
325	                    break;
326	                }
327	                Some(b'\\') => {
328	                    self.pos += 1;
329	                    match self.peek() {
330	                        Some(b'"') => out.push('"'),
331	                        Some(b'\\') => out.push('\\'),
332	                        Some(b'/') => out.push('/'),
333	                        Some(b'b') => out.push('\u{0008}'),
334	                        Some(b'f') => out.push('\u{000C}'),
335	                        Some(b'n') => out.push('\n'),
336	                        Some(b'r') => out.push('\r'),
337	                        Some(b't') => out.push('\t'),
338	                        Some(b'u') => {
339	                            self.pos += 1;
340	                            let cp = self.parse_hex4()?;
341	                            // High surrogate demands a matching low surrogate.
342	                            let cp = if (0xD800..=0xDBFF).contains(&cp) {
343	                                if self.peek() != Some(b'\\') {
344	                                    return Err("lone high surrogate".to_string());
345	                                }
346	                                self.pos += 1;
347	                                if self.peek() != Some(b'u') {
348	                                    return Err("lone high surrogate".to_string());
349	                                }
350	                                self.pos += 1;
351	                                let lo = self.parse_hex4()?;
352	                                if !(0xDC00..=0xDFFF).contains(&lo) {
353	                                    return Err("high surrogate not followed by a low surrogate".to_string());
354	                                }
355	                                0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)
356	                            } else if (0xDC00..=0xDFFF).contains(&cp) {
357	                                return Err("lone low surrogate".to_string());
358	                            } else {
359	                                cp
360	                            };
361	                            match char::from_u32(cp) {
362	                                Some(c) => out.push(c),
363	                                None => return Err("invalid unicode escape".to_string()),
364	                            }
365	                            continue;
366	                        }
367	                        _ => return Err("invalid escape sequence".to_string()),
368	                    }
369	                    self.pos += 1;
370	                }
371	                Some(_) => {
372	                    // Copy a run of ordinary bytes, reinterpreting the slice as
373	                    // UTF-8 for appending; control characters and invalid UTF-8
374	                    // inside a string are rejected. The run stops at ASCII
375	                    // delimiters only, so a multibyte sequence is never split.
376	                    let start = self.pos;
377	                    while self.pos < self.bytes.len() {
378	                        let b = self.bytes[self.pos];
379	                        if b == b'"' || b == b'\\' {
380	                            break;
381	                        }
382	                        if b < 0x20 {
383	                            return Err("unescaped control character in string".to_string());
384	                        }
385	                        self.pos += 1;
386	                    }
387	                    match std::str::from_utf8(&self.bytes[start..self.pos]) {
388	                        Ok(s) => out.push_str(s),
389	                        Err(_) => return Err("string is not valid UTF-8".to_string()),
390	                    }
391	                }
392	            }
393	        }
394	        Ok(out)
395	    }
396	
397	    fn parse_hex4(&mut self) -> Result<u32, String> {
398	        if self.pos + 4 > self.bytes.len() {
399	            return Err("truncated unicode escape".to_string());
400	        }
401	        let mut v = 0u32;
402	        for _ in 0..4 {
403	            let b = self.bytes[self.pos];
404	            self.pos += 1;
405	            let n = match b {
406	                b'0'..=b'9' => u32::from(b - b'0'),
407	                b'a'..=b'f' => u32::from(b - b'a' + 10),
408	                b'A'..=b'F' => u32::from(b - b'A' + 10),
409	                _ => return Err("invalid hex digit in unicode escape".to_string()),
410	            };
411	            v = (v << 4) | n;
412	        }
413	        Ok(v)
414	    }
415	
416	    /// A JSON number accepted only when it is an exact unsigned 64-bit
417	    /// integer token: digits only, no sign, fraction or exponent.
418	    fn parse_u64(&mut self) -> Result<u64, String> {
419	        let start = self.pos;
420	        while self.peek().is_some_and(|b| b.is_ascii_digit()) {
421	            self.pos += 1;
422	        }
423	        if start == self.pos {
424	            return Err("expected an unsigned integer".to_string());
425	        }
426	        // Canonical JSON integer token: "0" alone is allowed, but no leading
427	        // zeros (so "01" is rejected, not read as 1).
428	        if self.pos - start > 1 && self.bytes[start] == b'0' {
429	            return Err("integer must not have leading zeros".to_string());
430	        }
431	        if self.peek().is_some_and(|b| matches!(b, b'.' | b'e' | b'E' | b'+' | b'-')) {
432	            return Err("number must be an unsigned 64-bit integer".to_string());
433	        }
434	        let text = std::str::from_utf8(&self.bytes[start..self.pos])
435	            .map_err(|_| "integer is not ASCII".to_string())?;
436	        let mut value: u64 = 0;
437	        for b in text.bytes() {
438	            value = value
439	                .checked_mul(10)
440	                .and_then(|v| v.checked_add(u64::from(b - b'0')))
441	                .ok_or_else(|| "integer exceeds unsigned 64-bit range".to_string())?;
442	        }
443	        Ok(value)
444	    }
445	
446	    /// A JSON string that must contain exactly 64 lowercase hexadecimal
447	    /// characters, decoded to 32 bytes.
448	    fn parse_hash(&mut self) -> Result<[u8; 32], String> {
449	        let s = self.parse_string()?;
450	        if s.len() != 64 || !s.bytes().all(is_lower_hex) {
451	            return Err("hash must be a string of 64 lowercase hexadecimal characters".to_string());
452	        }
453	        let bytes = s.as_bytes();
454	        let mut out = [0u8; 32];
455	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
456	            out[i] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
457	        }
458	        Ok(out)
459	    }
460	
461	    fn parse_hash_array(&mut self) -> Result<Vec<[u8; 32]>, String> {
462	        self.eat(b'[')?;
463	        let mut hashes = Vec::new();
464	        self.ws();
465	        if self.peek() == Some(b']') {
466	            self.pos += 1;
467	            return Ok(hashes);
468	        }
469	        loop {
470	            self.ws();
471	            hashes.push(self.parse_hash()?);
472	            self.ws();
473	            match self.peek() {
474	                Some(b',') => {
475	                    self.pos += 1;
476	                }
477	                Some(b']') => {
478	                    self.pos += 1;
479	                    break;
480	                }
481	                _ => return Err(format!("expected ',' or ']' at byte {}", self.pos)),
482	            }
483	        }
484	        Ok(hashes)
485	    }
486	}
