488	/// Check a well-formed proof against the independently trusted tree size and
489	/// root, exactly per RFC 6962 section 2.1.1:
490	///
491	/// 1. the proof's `tree_size` must equal the trusted size (the proof must not
492	///    name its own trust anchor);
493	/// 2. the proof's `root` must equal the trusted root;
494	/// 3. `leaf_index` must exist in a tree of that size (already enforced while
495	///    parsing);
496	/// 4. starting from SHA-256(0x00 || record), the audit path hashes must
497	///    recombine in the order dictated by the (possibly uneven) tree geometry
498	///    into that root, consuming every supplied hash exactly once.
499	///
500	/// Duplicate content is never searched for: the check is against the exact
501	/// `leaf_index` the proof claims. A single-record tree needs an empty path;
502	/// a path that is too short or too long for the geometry cannot succeed.
503	fn verify_proof(proof: &Proof, record: &[u8], trusted_size: u64, trusted_root: &[u8; 32]) -> Result<(), String> {
504	    if proof.tree_size != trusted_size {
505	        return Err(format!(
506	            "proof tree_size {} does not match the trusted tree size {trusted_size}",
507	            proof.tree_size
508	        ));
509	    }
510	    if proof.root != *trusted_root {
511	        return Err("proof root does not match the trusted root".to_string());
512	    }
513	    let computed = include_record(
514	        leaf_hash(record),
515	        proof.leaf_index,
516	        proof.tree_size,
517	        &proof.audit_path,
518	    )
519	    .map_err(|e| e.to_string())?;
520	    if computed != *trusted_root {
521	        return Err("record bytes or audit_path do not match the root at the claimed position".to_string());
522	    }
523	    Ok(())
524	}
525	
526	/// RFC 6962-bis recursive inclusion recomputation: the combination order is
527	/// derived from the subtree sizes, and the path is consumed in its given
528	/// leaf-to-root order. A missing sibling or an unconsumed leftover hash is an
529	/// error, so an over- or under-long path never verifies. Arithmetic stays in
530	/// u64 so sizes above `usize::MAX` cannot truncate on a 32-bit platform; the
531	/// recursion depth is bounded by the hashes actually present in the path.
532	fn include_record(
533	    leaf: [u8; 32],
534	    m: u64,
535	    n: u64,
536	    path: &[[u8; 32]],
537	) -> Result<[u8; 32], String> {
538	    fn sub(
539	        leaf: [u8; 32],
540	        m: u64,
541	        n: u64,
542	        path: &[[u8; 32]],
543	        pos: &mut usize,
544	    ) -> Result<[u8; 32], String> {
545	        if n == 1 {
546	            return Ok(leaf);
547	        }
548	        // Largest power of two strictly smaller than n.
549	        let k = 1u64 << (u64::BITS - 1 - (n - 1).leading_zeros());
550	        if m < k {
551	            let left = sub(leaf, m, k, path, pos)?;
552	            let right = take(path, pos)?;
553	            Ok(node_hash(&left, &right))
554	        } else {
555	            let right = sub(leaf, m - k, n - k, path, pos)?;
556	            let left = take(path, pos)?;
557	            Ok(node_hash(&left, &right))
558	        }
559	    }
560	    fn take(path: &[[u8; 32]], pos: &mut usize) -> Result<[u8; 32], String> {
561	        let h = *path
562	            .get(*pos)
563	            .ok_or_else(|| "audit_path is shorter than the tree requires".to_string())?;
564	        *pos += 1;
565	        Ok(h)
566	    }
567	    let mut pos = 0;
568	    let root = sub(leaf, m, n, path, &mut pos)?;
569	    if pos != path.len() {
570	        return Err("audit_path is longer than the tree requires".to_string());
571	    }
572	    Ok(root)
573	}
