590	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data). The prefix byte and
591	/// the record are fed to the hasher as two consecutive slices, so hashing a
592	/// record of any length needs no copy of the record and no allocation beyond
593	/// the hasher's fixed-size state.
594	fn leaf_hash(data: &[u8]) -> [u8; 32] {
595	    let mut h = Sha256::new();
596	    h.update(&[0x00]);
597	    h.update(data);
598	    h.finalize()
599	}
