601	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
602	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
603	    let mut h = Sha256::new();
604	    h.update(&[0x01]);
605	    h.update(left);
606	    h.update(right);
607	    h.finalize()
608	}
