610	/// Construct the RFC 6962 Merkle tree over a batch. This is the SINGLE place
611	/// that maintains the tree-construction rules: both `root` (via `mth`) and
612	/// `prove` (via `root_and_path`) build their leaves and subtrees here, so the
613	/// two commands can never disagree on how a batch is shaped or hashed.
614	///
615	/// ```text
616	/// MTH([])      = SHA-256("")
617	/// MTH([d])     = SHA-256(0x00 || d)
618	/// MTH(d0..dn)  = SHA-256(0x01 || MTH(d0..dk) || MTH(dk..dn))
619	/// ```
620	///
621	/// with k the largest power of two strictly smaller than n. Uneven batches
622	/// are handled by the recursion itself: no leaf is duplicated and no empty
623	/// record is appended to round the size up to a power of two.
624	///
625	/// `target` selects the one leaf a membership proof is built for:
626	///
627	/// ```text
628	/// PATH(m, [d0]) = []
629	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
630	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
631	/// ```
632	///
633	/// When `target` is `Some(m)`, the sibling subtree hashes on the route from
634	/// leaf `m` to the root are appended to `path` in leaf-to-root order
635	/// (RFC 6962 section 2.1.1); the reindexed `Some(m - k)` follows the audited
636	/// leaf into whichever subtree contains it, while the sibling subtree is
637	/// built with `None`. With `None` only the root is built. Every leaf hash and
638	/// every interior hash is computed exactly once in either mode, so producing
639	/// a proof costs the same 2n - 1 SHA-256 invocations as the root alone.
640	fn build_tree(
641	    leaves: &[&[u8]],
642	    target: Option<usize>,
643	    path: &mut Vec<[u8; 32]>,
644	) -> [u8; 32] {
645	    match leaves.len() {
646	        0 => sha256(&[]),
647	        1 => leaf_hash(leaves[0]),
648	        n => {
649	            // Largest power of two strictly smaller than n.
650	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
651	            let (left_leaves, right_leaves) = leaves.split_at(k);
652	            match target {
653	                // The audited leaf is in the left subtree; the right subtree
654	                // hash is this level's sibling on the leaf-to-root path.
655	                Some(m) if m < k => {
656	                    let left = build_tree(left_leaves, Some(m), path);
657	                    let right = build_tree(right_leaves, None, path);
658	                    path.push(right);
659	                    node_hash(&left, &right)
660	                }
661	                // The audited leaf is in the right subtree; reindex it
662	                // relative to that subtree and take the left subtree as the
663	                // sibling.
664	                Some(m) => {
665	                    let left = build_tree(left_leaves, None, path);
666	                    let right = build_tree(right_leaves, Some(m - k), path);
667	                    path.push(left);
668	                    node_hash(&left, &right)
669	                }
670	                // No audited leaf: both subtrees are plain root constructions.
671	                None => {
672	                    let left = build_tree(left_leaves, None, path);
673	                    let right = build_tree(right_leaves, None, path);
674	                    node_hash(&left, &right)
675	                }
676	            }
677	        }
678	    }
679	}
