681	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256: the batch root, built
682	/// by the shared `build_tree` constructor so it follows exactly the same
683	/// rules as proof generation.
684	#[doc(hidden)]
685	pub fn mth(leaves: &[&[u8]]) -> [u8; 32] {
686	    build_tree(leaves, None, &mut Vec::new())
687	}
