689	/// RFC 6962 section 2.1.1: the Merkle Tree Hash of the whole batch together
690	/// with the Merkle Audit Path for the record at `m`, both produced by the
691	/// shared `build_tree` constructor. The returned path is ordered from the
692	/// leaf level up to the root and is empty for a batch of exactly one record.
693	#[doc(hidden)]
694	pub fn root_and_path(leaves: &[&[u8]], m: usize) -> ([u8; 32], Vec<[u8; 32]>) {
695	    let n = leaves.len();
696	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
697	    let mut path = Vec::new();
698	    let root = build_tree(leaves, Some(m), &mut path);
699	    (root, path)
700	}
