703	pub fn hex(digest: &[u8; 32]) -> String {
704	    let mut s = String::with_capacity(64);
705	    for b in digest {
706	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
707	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
708	    }
709	    s
710	}
