713	/// leaf_index, the lowercase-hex root, and the audit path as a JSON array of
714	/// lowercase-hex hashes ordered leaf to root.
715	#[doc(hidden)]
716	pub fn proof_json(tree_size: u64, leaf_index: u64, root: &[u8; 32], audit_path: &[[u8; 32]]) -> String {
717	    let mut out = String::new();
718	    out.push_str("{\"tree_size\":");
