768	/// Streaming SHA-256 (FIPS 180-4). The working state is the eight hash words
769	/// plus one 64-byte block buffer, so the temporary memory a hash needs is a
770	/// small constant no matter how long the hashed input is: a record is fed in
771	/// place from the batch buffer and is never copied for hashing.
772	struct Sha256 {
773	    h: [u32; 8],
774	    buf: [u8; 64],
775	    buf_len: usize,
776	    total_len: u64,
777	}
778	
779	impl Sha256 {
780	    fn new() -> Self {
781	        #[cfg(test)]
782	        SHA256_CALLS.with(|c| c.set(c.get() + 1));
783	        Sha256 {
784	            h: [
785	                0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
786	                0x1f83d9ab, 0x5be0cd19,
787	            ],
788	            buf: [0u8; 64],
789	            buf_len: 0,
790	            total_len: 0,
791	        }
792	    }
793	
794	    /// Feed the next chunk of input. Bytes are consumed straight from `data`;
795	    /// only a partial trailing block is ever staged in `buf`.
796	    fn update(&mut self, mut data: &[u8]) {
797	        self.total_len = self.total_len.wrapping_add(data.len() as u64);
798	        if self.buf_len > 0 {
799	            let take = (64 - self.buf_len).min(data.len());
800	            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&data[..take]);
801	            self.buf_len += take;
802	            data = &data[take..];
803	            if self.buf_len == 64 {
804	                let block = self.buf;
805	                self.compress(&block);
806	                self.buf_len = 0;
807	            }
808	        }
809	        while data.len() >= 64 {
810	            let (block, rest) = data.split_at(64);
811	            let mut staged = [0u8; 64];
812	            staged.copy_from_slice(block);
813	            self.compress(&staged);
814	            data = rest;
815	        }
816	        if !data.is_empty() {
817	            self.buf[..data.len()].copy_from_slice(data);
818	            self.buf_len = data.len();
819	        }
820	    }
821	
822	    /// Append the FIPS 180-4 padding (0x80, zeros, 64-bit big-endian bit
823	    /// length) inside the block buffer and produce the digest. At most one
824	    /// extra block is needed when the length field does not fit after the
825	    /// final data byte.
826	    fn finalize(mut self) -> [u8; 32] {
827	        let bit_len = self.total_len.wrapping_mul(8);
828	        self.update(&[0x80]);
829	        while self.buf_len != 56 {
830	            self.update(&[0]);
831	        }
832	        self.update(&bit_len.to_be_bytes());
833	        debug_assert_eq!(self.buf_len, 0, "padding must end on a block boundary");
834	
835	        let mut out = [0u8; 32];
836	        for (i, word) in self.h.iter().enumerate() {
837	            out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
838	        }
839	        out
840	    }
841	
842	    /// The SHA-256 compression function over one 64-byte block.
843	    fn compress(&mut self, block: &[u8; 64]) {
844	        let mut w = [0u32; 64];
845	        for (i, word) in block.chunks_exact(4).enumerate() {
846	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
847	        }
848	        for i in 16..64 {
849	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
850	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
851	            w[i] = w[i - 16]
852	                .wrapping_add(s0)
853	                .wrapping_add(w[i - 7])
854	                .wrapping_add(s1);
855	        }
856	
857	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = self.h;
858	        for i in 0..64 {
859	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
860	            let ch = (e & f) ^ ((!e) & g);
861	            let t1 = hh
862	                .wrapping_add(s1)
863	                .wrapping_add(ch)
864	                .wrapping_add(K[i])
865	                .wrapping_add(w[i]);
866	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
867	            let maj = (a & b) ^ (a & c) ^ (b & c);
868	            let t2 = s0.wrapping_add(maj);
869	            hh = g;
870	            g = f;
871	            f = e;
872	            e = d.wrapping_add(t1);
873	            d = c;
874	            c = b;
875	            b = a;
876	            a = t1.wrapping_add(t2);
877	        }
878	
879	        self.h[0] = self.h[0].wrapping_add(a);
880	        self.h[1] = self.h[1].wrapping_add(b);
881	        self.h[2] = self.h[2].wrapping_add(c);
882	        self.h[3] = self.h[3].wrapping_add(d);
883	        self.h[4] = self.h[4].wrapping_add(e);
884	        self.h[5] = self.h[5].wrapping_add(f);
885	        self.h[6] = self.h[6].wrapping_add(g);
886	        self.h[7] = self.h[7].wrapping_add(hh);
887	    }
