898	    /// Verify an RFC 6962 inclusion proof with the RFC's recursive verifier:
899	    /// it re-derives the combination order from the tree geometry (k =
900	    /// largest power of two below the current subtree size) while consuming
901	    /// exactly the supplied sibling hashes. A wrong length, order or hash
902	    /// fails; the root computed here must equal the tree root.
903	    fn rfc_recompute_root(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
904	        assert!(m < n);
905	        fn sub(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]], pos: &mut usize) -> [u8; 32] {
906	            if n == 1 {
907	                return leaf_hash(leaf);
908	            }
909	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
910	            if m < k {
911	                let left = sub(leaf, m, k, path, pos);
912	                assert!(*pos < path.len(), "proof too short");
913	                let right = path[*pos];
914	                *pos += 1;
915	                node_hash(&left, &right)
916	            } else {
917	                let right = sub(leaf, m - k, n - k, path, pos);
918	                assert!(*pos < path.len(), "proof too short");
919	                let left = path[*pos];
920	                *pos += 1;
921	                node_hash(&left, &right)
922	            }
923	        }
924	        let mut pos = 0;
925	        let root = sub(leaf, m, n, path, &mut pos);
926	        assert_eq!(pos, path.len(), "proof too long: {pos} consumed of {}", path.len());
927	        root
928	    }
