1362	    fn verify_accepts_real_proofs_at_every_position_of_many_sizes() {
1363	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 257]).collect();
1364	        for n in sizes {
1365	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
1366	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1367	            let root = mth(&refs);
1368	            for m in 0..n {
1369	                verify_record(&refs, m, refs[m], n as u64).unwrap_or_else(|e| {
1370	                    panic!("n={n} m={m} must verify: {e}")
1371	                });
1372	                // The proof must not be trusted by itself: a different
1373	                // trusted size or root always fails.
1374	                assert!(verify_record(&refs, m, refs[m], n as u64 + 1).is_err());
1375	                let mut other_root = root;
1376	                other_root[0] ^= 0x01;
1377	                let (_, path) = root_and_path(&refs, m);
1378	                let bytes = proof_json(n as u64, m as u64, &root, &path).into_bytes();
1379	                let proof = parse_proof(&bytes).unwrap();
1380	                assert!(verify_proof(&proof, refs[m], n as u64, &other_root).is_err());
1381	            }
1382	        }
1383	    }
