1457	    fn include_record_matches_recursive_verifier_and_checks_length() {
1458	        // Cross-check the command's verifier against the test-module RFC
1459	        // verifier across geometries, and pin short/long path rejection.
1460	        for n in 1..=20usize {
1461	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("r{i}").into_bytes()).collect();
1462	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
1463	            let root = mth(&refs);
