1648	    #[test]
1649	    fn api_keeps_full_64bit_meaning_of_size_and_index() {
1650	        // A synthetic proof for a tree of 2^63 records at index 2^32: the
1651	        // audit path element i is the 64-char lowercase hex of i, and the
1652	        // trusted root is recomputed here with the internal verifier. The
1653	        // point is that u64 sizes/indices flow through verify_membership
1654	        // untruncated and come back in the Membership result unchanged.
1655	        let record = b"big-tree-record\x00\xff\xfe";
1656	        let size: u64 = 1 << 63;
1657	        let index: u64 = 1 << 32;
1658	        let path: Vec<[u8; 32]> = (0..63u64)
1659	            .map(|i| {
1660	                let s = format!("{i:064x}");
1661	                let mut h = [0u8; 32];
1662	                for (j, pair) in s.as_bytes().chunks_exact(2).enumerate() {
1663	                    h[j] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
1664	                }
1665	                h
1666	            })
1667	            .collect();
1668	        let root = include_record(leaf_hash(record), index, size, &path).unwrap();
1669	        let proof = proof_json(size, index, &root, &path).into_bytes();
1670	        let m = verify_membership(record, &proof, size, &root).expect("2^63 tree must verify");
1671	        assert_eq!(m.leaf_index(), 1u64 << 32);
1672	        assert_eq!(m.tree_size(), 1u64 << 63);
1673	        assert_eq!(m.root(), &root);
1674	        // Off by one in the trusted size or the claimed index must fail, not
1675	        // truncate to a smaller tree.
1676	        assert!(matches!(
1677	            verify_membership(record, &proof, size - 1, &root),
1678	            Err(VerifyError::VerificationFailed(_))
1679	        ));
1680	        let off = proof_json(size, index + 1, &root, &path).into_bytes();
1681	        assert!(matches!(
1682	            verify_membership(record, &off, size, &root),
1683	            Err(VerifyError::VerificationFailed(_))
1684	        ));
1685	    }
1686	}
