1	//! End-to-end regression tests for `roottrace root` with LONG records whose
2	//! lengths approach and cross the SHA-256 padding/block boundaries.
3	//!
4	//! A leaf is hashed as SHA-256(0x00 || record). Record lengths 54/55/56 make
5	//! the leaf input 55/56/57 bytes (the 0x80 padding terminator and the 64-bit
6	//! length field crowd the 56-byte boundary and spill into a second block),
7	//! lengths 63/64/65 make it 64/65/66 bytes (exactly one block, then one and
8	//! two bytes into the next), and L135's leaf input is 136 bytes (content
9	//! reaches a third block). A block walk that drops the tail, counts a span
10	//! twice, pads wrong, or splits one record into several yields a different
11	//! root, which the fixed vectors below pin down.
12	//!
13	//! Expected roots are FIXED constants produced independently of roottrace by
14	//! `tests/reference/rfc6962_vectors.py` (standard-library `hashlib.sha256`,
15	//! recursive definition and stack fold agreeing); they are never derived
16	//! from roottrace output. The long record byte literals are copied from the
17	//! same generator, so the single-record batches and the mixed batch hash the
18	//! very same record bytes - a long record follows one standard on its own and
19	//! inside a batch.
20	//!
21	//! Every long record contains NUL, CR and non-UTF-8 bytes in its interior and
22	//! ends on a non-text byte, so no text decoding, CR/LF normalization or
23	//! NUL-based truncation can go unnoticed.
24	
25	mod common;
26	
27	use common::{assert_root, join_lf};
28	
29	// --- Fixed long records (raw record bytes, WITHOUT the LF separator) -------
30	// Copied verbatim from tests/reference/rfc6962_vectors.py output.
31	
32	const REC_L54: &[u8] =
33	    b"L54:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghi\x00";
34	const REC_L55: &[u8] =
35	    b"L55:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghij\r";
36	const REC_L56: &[u8] =
37	    b"L56:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijk\xff";
38	const REC_L63: &[u8] =
39	    b"L63:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqr\x00";
40	const REC_L64: &[u8] =
41	    b"L64:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrs\r";
42	const REC_L65: &[u8] =
43	    b"L65:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrst\xfe";
44	const REC_L135: &[u8] = b"L135:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopq\xff";
45	
46	// Tail-byte variants: identical to the original except for the very last
47	// byte. Their fixed roots correspond to the whole MODIFIED record.
48	const REC_L65_M: &[u8] =
49	    b"L65:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstZ";
50	const REC_L135_M: &[u8] = b"L135:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopq~";
51	
52	// Independently fixed RFC 6962 roots (tests/reference/rfc6962_vectors.py).
53	const ROOT_L54: &str = "c20ba1db777b396463af4e4d7defeb24472fb84a1dfcecdceebd62b05d8fbe5f";
54	const ROOT_L55: &str = "fea596a972f814904aac2bfaf3ed800937bc9fc7157174db9c8ac18e799635fb";
55	const ROOT_L56: &str = "3088506400b3153087723150df0f2368e4d476e37b2d255e0ceb43e99c830d1b";
56	const ROOT_L63: &str = "27e0fa0bbbdcc1e98422f0c9d5009ed6c9985492ad2ea043ef6151abbe6647df";
57	const ROOT_L64: &str = "cf194ddfdf737250e35d68be5a46bacb8686b83658f94c9c954389c1be083270";
58	const ROOT_L65: &str = "0c516c35707fdd7ce8110d5257a639e9088c51b4186dcf0e4239e043973afe2b";
59	const ROOT_L135: &str = "32f07c1f5187e59d842b36d33a004fcfaa70c8962d32d0e920a57051496b675e";
60	const ROOT_L65_M: &str = "749532458c5a679a6eeb5ddb2cbc5c2b7fe7cf961c0a9e3fe1201d727b2a1653";
61	const ROOT_L135_M: &str = "0f69f3b46fdb491cbd29e4ecbaa48764101d6249ab54287bc2591c18f69d4130";
62	
63	/// (name, exact record bytes, fixed root of the one-record batch).
64	const SINGLE_LONG: &[(&str, &[u8], &str)] = &[
65	    ("L54", REC_L54, ROOT_L54),
66	    ("L55", REC_L55, ROOT_L55),
67	    ("L56", REC_L56, ROOT_L56),
68	    ("L63", REC_L63, ROOT_L63),
69	    ("L64", REC_L64, ROOT_L64),
70	    ("L65", REC_L65, ROOT_L65),
71	    ("L135", REC_L135, ROOT_L135),
72	];
73	
74	/// Fixed batch of long AND short records (10 records; RFC 6962 splits k=8, so
75	/// long records at positions 2/4/6 land in the left subtree and the one at
76	/// position 8 in the right subtree). It also holds an empty record and short
77	/// records carrying CR, NUL and non-UTF-8 bytes.
78	const MIXED_RECORDS: &[&[u8]] = &[
79	    b"alpha",
80	    b"",
81	    REC_L54,
82	    b"beta\r",
83	    REC_L63,
84	    b"\xff\x00z",
85	    REC_L135,
86	    b"middle",
87	    REC_L65,
88	    b"end-record\x01",
89	];
90	const ROOT_MIXED: &str = "3a460e4bda163253da14917c2f9c63208d1b24e3d285c763d2f6c6dedec6694b";
91	
92	/// MIXED with exactly one byte changed: the final byte of the L65 record at
93	/// position 8.
94	const MIXED_M_RECORDS: &[&[u8]] = &[
95	    b"alpha",
96	    b"",
97	    REC_L54,
98	    b"beta\r",
99	    REC_L63,
100	    b"\xff\x00z",
101	    REC_L135,
102	    b"middle",
103	    REC_L65_M,
104	    b"end-record\x01",
105	];
106	const ROOT_MIXED_M: &str = "71cc24ac8aa1e4e4c95ca35704b0ec4302323659479d3e46134fcb359ab2858e";
107	
108	/// Structural invariants every long record must satisfy: the exact required
109	/// raw length (LF excluded), no LF inside, and NUL/CR/non-UTF-8 bytes in the
110	/// interior.
111	fn assert_long_record_shape(name: &str, rec: &[u8], expected_len: usize) {
112	    assert_eq!(
113	        rec.len(),
114	        expected_len,
115	        "{name}: record length is the raw byte count without the LF separator"
116	    );
117	    assert!(!rec.contains(&b'\n'), "{name}: records must not contain LF");
118	    assert!(rec.contains(&0x00), "{name}: NUL must appear inside the record");
119	    assert!(rec.contains(&0x0D), "{name}: CR must appear inside the record");
120	    assert!(
121	        rec.iter().any(|&b| b >= 0x80),
122	        "{name}: non-UTF-8 bytes must appear inside the record"
123	    );
124	}
125	
126	#[test]
127	fn long_records_cover_the_required_lengths_and_binary_content() {
128	    let lengths: Vec<usize> = SINGLE_LONG.iter().map(|(_, rec, _)| rec.len()).collect();
129	    assert_eq!(lengths, vec![54, 55, 56, 63, 64, 65, 135]);
130	    assert!(REC_L135.len() > 128, "a record longer than 128 bytes is required");
131	    for (name, rec, _) in SINGLE_LONG {
132	        assert_long_record_shape(name, rec, rec.len());
133	        // Every base record also ends on a non-text byte, so binary fidelity
134	        // is exercised at the tail as well as in the interior.
135	        assert!(
136	            matches!(rec[rec.len() - 1], 0x00 | 0x0D | 0x80..=0xFF),
137	            "{name}: the record must end on a non-text byte, got {:#04x}",
138	            rec[rec.len() - 1]
139	        );
140	    }
141	    // Tail variants keep the exact same length and interior binary shape;
142	    // their final byte is the one deliberately changed byte (ASCII here).
143	    assert_long_record_shape("L65_M", REC_L65_M, 65);
144	    assert_long_record_shape("L135_M", REC_L135_M, 135);
145	    assert_eq!(REC_L65_M.last(), Some(&b'Z'));
146	    assert_eq!(REC_L135_M.last(), Some(&b'~'));
147	}
148	
149	#[test]
150	fn each_long_record_as_a_single_record_batch_matches_its_fixed_root() {
151	    for (name, rec, expected) in SINGLE_LONG {
152	        let records: &[&[u8]] = &[*rec];
153	        // With and without the LF that terminates the single record: the file
154	        // encodes the same one-record sequence and has the same fixed root.
155	        assert_root(
156	            &format!("{name}: one {}-byte record, trailing LF", rec.len()),
157	            records,
158	            &join_lf(records, true),
159	            expected,
160	        );
161	        assert_root(
162	            &format!("{name}: one {}-byte record, no trailing LF", rec.len()),
163	            records,
164	            &join_lf(records, false),
165	            expected,
166	        );
167	    }
168	}
169	
170	#[test]
171	fn every_boundary_length_has_its_own_distinct_fixed_root() {
172	    // Adjacent lengths (e.g. 63/64/65 straddling the 64-byte block) must not
173	    // collapse onto one another through padding or truncation.
174	    for (i, (n1, _, r1)) in SINGLE_LONG.iter().enumerate() {
175	        for (n2, _, r2) in &SINGLE_LONG[i + 1..] {
176	            assert_ne!(r1, r2, "{n1}-byte and {n2}-byte records need distinct roots");
177	        }
178	    }
179	}
180	
181	#[test]
182	fn changing_one_byte_near_the_end_matches_the_modified_records_fixed_root() {
183	    // L65: only the final 0xfe byte becomes 'Z'.
184	    assert_eq!(REC_L65_M.len(), REC_L65.len());
185	    assert_eq!(REC_L65_M[..REC_L65.len() - 1], REC_L65[..REC_L65.len() - 1]);
186	    assert_ne!(REC_L65_M.last(), REC_L65.last());
187	    // L135 (>128 bytes): only the final 0xff byte becomes '~'.
188	    assert_eq!(REC_L135_M.len(), REC_L135.len());
189	    assert_eq!(REC_L135_M[..REC_L135.len() - 1], REC_L135[..REC_L135.len() - 1]);
190	    assert_ne!(REC_L135_M.last(), REC_L135.last());
191	    for (name, rec, root_modified, root_original) in [
192	        ("L65_M", REC_L65_M, ROOT_L65_M, ROOT_L65),
193	        ("L135_M", REC_L135_M, ROOT_L135_M, ROOT_L135),
194	    ] {
195	        let records: &[&[u8]] = &[rec];
196	        assert_root(
197	            &format!("{name}: full modified record, trailing LF"),
198	            records,
199	            &join_lf(records, true),
200	            root_modified,
201	        );
202	        assert_root(
203	            &format!("{name}: full modified record, no trailing LF"),
204	            records,
205	            &join_lf(records, false),
206	            root_modified,
207	        );
208	        assert_ne!(
209	            root_modified, root_original,
210	            "{name}: a one-byte change near the tail must change the root"
211	        );
212	    }
213	}
214	
215	#[test]
216	fn fixed_mixed_long_and_short_batch_matches_its_fixed_root() {
217	    assert_eq!(MIXED_RECORDS.len(), 10);
218	    // The same long-record constants used in the single-record batches appear
219	    // in the batch: one standard for long records on their own and in a batch.
220	    assert_eq!(MIXED_RECORDS[2], REC_L54);
221	    assert_eq!(MIXED_RECORDS[4], REC_L63);
222	    assert_eq!(MIXED_RECORDS[6], REC_L135);
223	    assert_eq!(MIXED_RECORDS[8], REC_L65);
224	    let long_positions = [2usize, 4, 6, 8];
225	    // RFC 6962 k=8 split for 10 records: long records on both sides.
226	    assert!(long_positions.iter().any(|&i| i < 8));
227	    assert!(long_positions.iter().any(|&i| i >= 8));
228	    // MIXED_M differs from MIXED only at record position 8 (last byte of L65).
229	    assert_eq!(MIXED_M_RECORDS[8], REC_L65_M);
230	    for i in 0..10 {
231	        if i != 8 {
232	            assert_eq!(MIXED_M_RECORDS[i], MIXED_RECORDS[i]);
233	        }
234	    }
235	
236	    // File size documents that LF bytes are separators, not record content:
237	    // records total 347 bytes; 9 between-record LFs give 356, terminating LF
238	    // gives 357.
239	    assert_eq!(join_lf(MIXED_RECORDS, false).len(), 356);
240	    assert_eq!(join_lf(MIXED_RECORDS, true).len(), 357);
241	
242	    assert_root(
243	        "MIXED: 10 long/short records, trailing LF",
244	        MIXED_RECORDS,
245	        &join_lf(MIXED_RECORDS, true),
246	        ROOT_MIXED,
247	    );
248	    assert_root(
249	        "MIXED: 10 long/short records, no trailing LF",
250	        MIXED_RECORDS,
251	        &join_lf(MIXED_RECORDS, false),
252	        ROOT_MIXED,
253	    );
254	    assert_root(
255	        "MIXED_M: last byte of the L65 record changed inside the batch",
256	        MIXED_M_RECORDS,
257	        &join_lf(MIXED_M_RECORDS, true),
258	        ROOT_MIXED_M,
259	    );
260	    assert_root(
261	        "MIXED_M: same modified batch without trailing LF",
262	        MIXED_M_RECORDS,
263	        &join_lf(MIXED_M_RECORDS, false),
264	        ROOT_MIXED_M,
265	    );
266	    assert_ne!(ROOT_MIXED, ROOT_MIXED_M, "the one tail byte participates in the batch root");
267	    // A batch containing the long record is not the same as the record alone.
268	    assert_ne!(ROOT_MIXED, ROOT_L135);
269	    assert_ne!(ROOT_MIXED_M, ROOT_L65_M);
270	}
