/// Incremental RFC 6962 Merkle Tree Hash over an LF-separated byte stream.
///
/// Bytes are fed through `feed` in chunks of any size; chunk boundaries are
/// meaningless to the result. Records are delimited by LF exactly as
/// `split_records` defines (the separator is not content, a trailing LF only
/// terminates the last record, an empty input is zero records), and the tree
/// is folded with the same largest-power-of-two split as `build_tree`, so
/// `finish` returns exactly `mth(&split_records(whole))` for the concatenation
/// `whole` of everything fed.
///
/// Memory use is a fixed amount plus at most 64 subtree hashes (one per bit
/// of the record count): nothing grows with the number of bytes fed or with
/// the length of any single record.
#[doc(hidden)]
pub struct RootStream {
    /// Hasher for the record currently being accumulated, primed with 0x00.
    leaf: Sha256,
    /// Whether any content byte of the current record has been seen. A record
    /// only exists once it has content or is terminated by LF, so an empty
    /// file is zero records and a trailing LF adds none.
    record_has_bytes: bool,
    /// Completed subtree hashes, bottom to top in strictly decreasing height.
    /// Each entry covers 2^height consecutive leaves; together they are the
    /// binary decomposition of the record count so far.
    subtrees: Vec<([u8; 32], u32)>,
}

