            None => sha256(&[]),
            Some((mut acc, _)) => {
                // Fold the remaining complete subtrees right to left; this is
                // the recursive k-split of build_tree read off the binary
                // decomposition of the record count.
                while let Some((left, _)) = self.subtrees.pop() {
                    acc = node_hash(&left, &acc);
                }
                acc
            }
        }
    }
