import hashlib
def stream_root(path):
    stack = []  # (hash, height)
    def push(h):
        hgt = 0
        while stack and stack[-1][1] == hgt:
            left, _ = stack.pop()
            h = hashlib.sha256(b'\x01' + left + h).digest()
            hgt += 1
        stack.append((h, hgt))
    leaf = hashlib.sha256(b'\x00')
    has_bytes = False
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(1 << 16)
            if not chunk: break
            for part in chunk.split(b'\n')[:-1] if b'\n' in chunk else []:
                pass
            # split keeping record semantics
            start = 0
            for i, b in enumerate(chunk):
                if b == 0x0a:
                    leaf.update(chunk[start:i]); has_bytes |= (i > start)
                    push(leaf.digest()); leaf = hashlib.sha256(b'\x00'); has_bytes = False
                    start = i + 1
            leaf.update(chunk[start:]); has_bytes |= (len(chunk) > start)
    if has_bytes:
        push(leaf.digest())
    if not stack:
        return hashlib.sha256(b'').hexdigest()
    acc, _ = stack.pop()
    while stack:
        left, _ = stack.pop()
        acc = hashlib.sha256(b'\x01' + left + acc).digest()
    return acc.hex()
for p in ('/tmp/big_many.bin', '/tmp/big_long.bin'):
    print(p, stream_root(p))
EOF
